args<-commandArgs(trailingOnly=TRUE);stopifnot(length(args)==1L);out<-args[1]
d<-read.csv(file.path(out,'adult_phenotype_frame.csv'),check.names=FALSE)
ors<-read.csv(file.path(out,'or_glm_crosscheck.csv'),check.names=FALSE)
m<-do.call(rbind,lapply(20261102:20261106,function(s){z<-read.csv(file.path(out,paste0('cv_metrics_',s,'.csv')));z$seed<-s;z}))
p<-read.csv(file.path(out,'cv_predictions_20261102.csv'))
stopifnot(nrow(d)==5501L,all(d$age>=18),length(unique(d$subjectid))==5294)
lev<-c('preserved_high_map','moderate_low_burden_or_variable_map','early_low_map_with_recovery','sustained_severe_hypotension_burden')
short<-c('Preserved high','Moderate/variable','Early low/recovery','Sustained severe')
colors<-c('#126982','#bf7735','#5b803c','#a53b4a')
d$trajectory_phenotype<-factor(d$trajectory_phenotype,levels=lev)
tab1<-do.call(rbind,lapply(lev,function(l){x<-d[d$trajectory_phenotype==l,];data.frame(phenotype=l,n=nrow(x),age_median=median(x$age),age_q1=unname(quantile(x$age,.25)),age_q3=unname(quantile(x$age,.75)),male_n=sum(x$sex=='M',na.rm=TRUE),icu_events=sum(x$icu_use),icu_rate=mean(x$icu_use))}))
tab2<-aggregate(d[,c('mean_map','min_map','sd_map','pct_time_lt_65','auc_per_hour_lt_65','early_map','middle_map','late_map')],list(phenotype=d$trajectory_phenotype),mean,na.rm=TRUE)
tab3<-do.call(rbind,lapply(split(m,m$model),function(x)data.frame(model=x$model[1],mean_auroc=mean(x$auroc),min_auroc=min(x$auroc),max_auroc=max(x$auroc),mean_brier=mean(x$brier),repeats=nrow(x))))
write.csv(tab1,file.path(out,'table1_adult.csv'),row.names=FALSE);write.csv(tab2,file.path(out,'table2_adult.csv'),row.names=FALSE);write.csv(tab3,file.path(out,'table3_adult_cv.csv'),row.names=FALSE)
render<-function(name,fun,w=7,h=5){pdf(file.path(out,paste0(name,'.pdf')),width=w,height=h);fun();dev.off();png(file.path(out,paste0(name,'.png')),width=w*300,height=h*300,res=300,type='cairo');fun();dev.off()}
render('Figure1_cohort_flow',function(){par(mar=c(1,1,2,1));plot.new();plot.window(xlim=c(0,1),ylim=c(0,1));title('Adult cohort construction',cex.main=1);ys<-c(.88,.69,.50,.31,.12);labs<-c('VitalDB cases: 6,388','Age at least 18 years: 6,331','Adult cases with selected MAP track: 6,329','General anesthesia, duration and coverage criteria: 5,501','Complete phenotype features: 5,501 (ICU use: 1,149)');for(i in seq_along(ys)){rect(.12,ys[i]-.055,.88,ys[i]+.055,border='#52616b');text(.5,ys[i],labs[i],cex=.8);if(i<length(ys))arrows(.5,ys[i]-.06,.5,ys[i+1]+.06,length=.07,col='#52616b')}})
render('Figure2_map_profile',function(){par(mar=c(5,5,3,2));dec<-paste0('map_decile_',1:10);means<-sapply(lev,function(l)colMeans(d[d$trajectory_phenotype==l,dec],na.rm=TRUE));matplot(1:10,means,type='l',lty=1,lwd=2.2,col=colors,xaxt='n',xlab='Relative operative time bin',ylab='Mean MAP (mmHg)',ylim=c(min(means,na.rm=TRUE)-1,max(means,na.rm=TRUE)+13));axis(1,1:10);legend('topright',legend=short,col=colors,lty=1,lwd=2,cex=.72,bty='n');title('Exploratory adult MAP profiles')})
render('Figure3_adjusted_or',function(){par(mar=c(5,11,3,2));idx<-match(paste0('trajectory_phenotype',lev[-1]),ors$term);z<-ors[idx,];plot(z$adjusted_or,3:1,xlim=range(c(.7,z$ci_high_subject_bootstrap))*c(.95,1.05),log='x',yaxt='n',xlab='Adjusted odds ratio (log scale)',ylab='',pch=19,col=colors[-1],cex=1.2);arrows(z$ci_low_subject_bootstrap,3:1,z$ci_high_subject_bootstrap,3:1,angle=90,code=3,length=.04,col=colors[-1]);abline(v=1,lty=2,col='grey45');axis(2,3:1,short[-1],las=1,cex.axis=.75);title('ICU use: reference = preserved high MAP')},w=8,h=5)
render('Figure4_calibration',function(){x<-p[p$model=='combined',];x<-x[order(x$p),];x$bin<-pmin(10,ceiling(seq_len(nrow(x))*10/nrow(x)));z<-aggregate(cbind(p,y)~bin,x,mean);plot(z$p,z$y,xlim=c(0,1),ylim=c(0,1),xaxs='i',yaxs='i',xlab='Mean out-of-fold predicted probability',ylab='Observed ICU use',pch=19,col='#126982');abline(0,1,lty=2,col='grey45');lines(z$p,z$y,col='#126982');title('Calibration: first grouped five-fold split')})
render('Figure5_model_performance',function(){ord<-c('base','traditional','phenotype','combined');z<-tab3[match(ord,tab3$model),];par(mar=c(5,10,3,2));plot(z$mean_auroc,4:1,xlim=c(.87,.92),yaxt='n',xlab='Pooled out-of-fold AUROC',ylab='',pch=19,col='#126982',xaxs='i');segments(z$min_auroc,4:1,z$max_auroc,4:1,col='#126982',lwd=2);axis(2,4:1,c('Base','Base + threshold','Base + phenotype','Combined'),las=1,cex.axis=.75);title('Five repeated grouped five-fold validations')},w=8,h=5)
